let payload = msg.payload;

// 1. Processa e invia i dati della Luce
if (payload.luce && payload.luce.indici) {
    payload.luce.indici.forEach(item => {
        let queryLuce = `INSERT IGNORE INTO storico_luce 
            (mese, pun_f1, pun_f2, pun_f3, spread, quota_fissa, dispacciamento) 
            VALUES (
                '${item.mese}', 
                ${item.pun_f1}, 
                ${item.pun_f2}, 
                ${item.pun_f3}, 
                ${payload.luce.spread_kwh}, 
                ${payload.luce.quota_fissa_mese}, 
                ${item.dispacciamento}
            );`;
        // Invia direttamente il messaggio configurando correttamente il msg.topic
        node.send({ topic: queryLuce, payload: "Esecuzione INSERT Luce" });
    });
}

// 2. Processa e invia i dati del Gas
if (payload.gas && payload.gas.indici) {
    payload.gas.indici.forEach(item => {
        let queryGas = `INSERT IGNORE INTO storico_gas 
            (mese, psv, spread, quota_fissa) 
            VALUES (
                '${item.mese}', 
                ${item.psv}, 
                ${payload.gas.spread_smc}, 
                ${payload.gas.quota_fissa_mese}
            );`;
        // Invia direttamente il messaggio configurando correttamente il msg.topic
        node.send({ topic: queryGas, payload: "Esecuzione INSERT Gas" });
    });
}

// Ritorniamo null per bloccare l'uscita standard, dato che abbiamo usato node.send()
return null;

let rows = msg.payload;

// Verifica se ci sono dati dal database
if (!rows || rows.length === 0) return null;

let ptsF1 = [];
let ptsF2 = [];
let ptsF3 = [];

rows.forEach(row => {
    // Creazione del timestamp in millisecondi per l'asse X
    let ts = new Date(row.mese + "-01T00:00:00Z").getTime();

    // Ci assicuriamo che i valori Y siano formattati rigorosamente come numeri
    // per evitare che un valore testuale mandato per errore blocchi il rendering
    ptsF1.push({ x: ts, y: Number(row.pun_f1) || 0 });
    ptsF2.push({ x: ts, y: Number(row.pun_f2) || 0 });
    ptsF3.push({ x: ts, y: Number(row.pun_f3) || 0 });
});

// La struttura esatta richiesta da node-red-dashboard per iniettare lo storico
msg.payload = [{
    "series": ["PUN F1", "PUN F2", "PUN F3"],
    "data": [
        ptsF1,
        ptsF2,
        ptsF3
    ],
    "labels": ["PUN F1", "PUN F2", "PUN F3"]
}];

return msg;

// ============================================================================
// INBOUND ROUTER LUCI
// Riceve i comandi on/off/scene. Supporta topic base dinamico.
// ============================================================================

let baseTopic = global.get("app_base_topic") || "zara/android/domotica";

// Estraiamo il nome del dispositivo usando un'Espressione Regolare.
// Cerca la stringa tra "/light/" e "/set"
// L'uso di RegExp previene crash se il baseTopic contiene caratteri speciali come '/'
let regexLight = new RegExp(`^${baseTopic}/light/([^/]+)/set$`);
let matchLight = msg.topic.match(regexLight);

let device = null;
let cmd = msg.payload.toString().toUpperCase();
let targetTopic = "";
let targetPayload = cmd;
let usaLinkInterno = false;

// Gestione speciale per le scene (che non passano per /light/)
if (msg.topic.includes("/scene/set")) {
    // Passa il messaggio intatto e lascia che sia il nodo Change a valle a gestirlo
    return [msg, null]; 
}

if (matchLight && matchLight[1]) {
    device = matchLight[1];
} else {
    // Se non è né una scena né una luce valida, scartalo
    return null; 
}

// Normalizzazione del comando
if (cmd === "TRUE" || cmd === "1") cmd = "ON";
if (cmd === "FALSE" || cmd === "0") cmd = "OFF";
targetPayload = cmd;

// Mappatura Dispositivi
switch (device) {
    case "skimmerPiscina":
    case "pompaPiscina":
    case "lavanderia":
    case "ingressoServizio":
    case "lampadaHifi":
    case "tavolinoLettura":
    case "portico":
    case "televisione":
    case "sala":
    case "libreria":
    case "luciPiscina":
    case "luciPedanaPiscina":
        targetPayload = cmd.toLowerCase(); // Trasforma "ON" in "on"
        usaLinkInterno = true;             // Attiva lo scambio verso l'uscita 2 (Link Nodes)
        break;

    case "esterno":
        targetTopic = "shellies/shelly1-esterno/relay/0/command";
        targetPayload = cmd.toLowerCase(); 
        break;

    case "cucina":
        targetTopic = "zigbee2mqtt/Luce_Cucina/set";
        targetPayload = { state: cmd };
        break;

    default:
        node.warn("Comando App ricevuto per luce non mappata: " + device);
        return null;
}

let messaggioInUscita = {
    topic: device, // Se usa il Link Interno, il topic sarà il nome del device
    payload: targetPayload
};

if (targetTopic !== "") {
    messaggioInUscita.topic = targetTopic; // Sovrascrive se c'è un topic MQTT hardware diretto
}

// IL DEVIATOIO FINALE (Outputs: 2)
if (usaLinkInterno) {
    return [null, messaggioInUscita];
} else {
    return [messaggioInUscita, null];
}

let inTopic = msg.topic;
let inPayload = msg.payload;

let targetDevice = "";
let deviceState = "OFF";

if (inTopic.includes("zara/domotics/lights/shelflamp")) {
    targetDevice = "libreria";
    deviceState = (typeof inPayload === 'object') ? inPayload.state : inPayload;
}
else if (inTopic.includes("shellies/shelly1-B8C284/relay/0")) {
    targetDevice = "lavanderia";
    deviceState = (typeof inPayload === 'object') ? inPayload.state : inPayload;
}
else if (inTopic.includes("shellies/shelly1-B92AF0/relay/0")) {
    targetDevice = "ingressoServizio";
    deviceState = (typeof inPayload === 'object') ? inPayload.state : inPayload;
}
else if (inTopic.includes("shellies/shelly1-771284/relay/0")) {
    targetDevice = "portico";
    deviceState = (typeof inPayload === 'object') ? inPayload.state : inPayload;
}
else if (inTopic.includes("zara/domotics/lights/poolpump")) {
    targetDevice = "pompaPiscina";
    deviceState = (typeof inPayload === 'object') ? inPayload.state : inPayload;
}
else if (inTopic.includes("zara/domotics/lights/poolskimmer")) {
    targetDevice = "skimmerPiscina";
    deviceState = (typeof inPayload === 'object') ? inPayload.state : inPayload;
}
else if (inTopic.includes("zara/domotics/lights/poolfloor")) {
    targetDevice = "luciPedanaPiscina";
    deviceState = (typeof inPayload === 'object') ? inPayload.state : inPayload;
}
else if (inTopic.includes("zara/domotics/lights/poollight")) {
    targetDevice = "luciPiscina";
    deviceState = (typeof inPayload === 'object') ? inPayload.state : inPayload;
}
else if (inTopic.includes("zara/domotics/lights/tvlamp")) {
    targetDevice = "televisione";
    deviceState = (typeof inPayload === 'object') ? inPayload.state : inPayload;
}
else if (inTopic.includes("zara/domotics/lights/livinglamp")) {
    targetDevice = "sala";
    deviceState = (typeof inPayload === 'object') ? inPayload.state : inPayload;
} 
else if (inTopic.includes("zigbee2mqtt/Luce_Cucina")) {
    targetDevice = "cucina";
    deviceState = (typeof inPayload === 'object') ? inPayload.state : inPayload;
}
else if (inTopic.includes("zigbee2mqtt/Luce_Libreria")) { // Usa il topic reale dell'hardware
    targetDevice = "libreria";
    deviceState = (typeof inPayload === 'object') ? inPayload.state : inPayload;
}
else if (inTopic.includes("shellies/shelly1-esterno")) {
    targetDevice = "esterno";
    deviceState = inPayload.toString().toUpperCase();
}
// --- LIBRERIA (Broadlink) ---
else if (inTopic === "zara/domotics/lights/readinglight") {
    targetDevice = "libreria";
    deviceState = inPayload.toString().toUpperCase(); // Trasforma "on" in "ON" per l'App
}
// ----------------------------
else {
    return null; 
}

if (deviceState === "ON" || deviceState === "on" || deviceState === "true") {
    deviceState = "ON";
} else {
    deviceState = "OFF";
}

// Usa il nuovo prefisso per la tua App
return {
    topic: `zara/android/domotica/light/${targetDevice}/state`,
    payload: deviceState
};

// --- GATEWAY TELEMETRIE: ENERGIA E PUFFER ---
let inTopic = msg.topic;
let payload = parseFloat(msg.payload);

// Se il payload non è un numero valido (es. stringhe o oggetti non parsati), usciamo
if (isNaN(payload)) return null;

const APP_BASE = global.get("app_base_topic", "file") || "zara/android/domotica";
let outTopic = "";
let outPayload = payload;

switch (inTopic) {
    // ==========================================
    // 1. PARAMETRI ENERGETICI (Tesla Powerwall)
    // ==========================================
    case "TeslaPowerwall/solar_instant_power":
        outTopic = `${APP_BASE}/energy/production`;
        // Filtro stabilità: arrotonda al kW o applica tolleranza se necessario
        outPayload = Math.round(payload); 

        // Anti-rimbalzo: invia solo se la variazione è maggiore di 15W
        let ultProd = flow.get("last_prod") || 0;
        if (Math.abs(outPayload - ultProd) < 15) return null;
        flow.set("last_prod", outPayload);
        break;

    case "TeslaPowerwall/load_instant_power":
        outTopic = `${APP_BASE}/energy/consumption`;
        outPayload = Math.round(payload);

        // Anti-rimbalzo: invia solo se la variazione è maggiore di 15W
        let ultCons = flow.get("last_cons") || 0;
        if (Math.abs(outPayload - ultCons) < 15) return null;
        flow.set("last_cons", outPayload);
        break;

    case "TeslaPowerwall/SOE":
        outTopic = `${APP_BASE}/energy/battery`;
        // Arrotonda la percentuale della batteria a un decimale
        outPayload = Math.round(payload * 10) / 10;
        break;

    // ==========================================
    // 2. RISCALDAMENTO E BOILER (Puffer)
    // ==========================================
    // Sostituisci i topic a sinistra con i tuoi topic hardware reali!
    case "emon/shellyACS/tempACS": 
        outTopic = `${APP_BASE}/acsPufferTemp`;
        outPayload = Math.round(payload * 10) / 10; // 1 decimale
        break;

    case "emon/resolDL2/sensor3":
        outTopic = `${APP_BASE}/pufferAltoTemp`;
        outPayload = Math.round(payload * 10) / 10;
        break;

    case "emon/resolDL2/sensor2":
        outTopic = `${APP_BASE}/pufferBassoTemp`;
        outPayload = Math.round(payload * 10) / 10;
        break;

    default:
        return null; // Ignora altri topic
}

// Spediamo il dato normalizzato verso l'app
return {
    topic: outTopic,
    payload: outPayload.toString() // L'app preferisce ricevere stringhe via MQTT
};

// ============================================================================
// INBOUND ROUTER TERMOSTATI
// Riceve i setpoint dall'App e li instrada verso AC o valvole Zigbee
// ============================================================================

let baseTopic = global.get("app_base_topic") || "zara/android/domotica";

// Estrazione dinamica della stanza (room) tramite RegEx.
// Cattura tutto ciò che sta tra "/thermostat/" e "/target/set"
let regexThermostat = new RegExp(`^${baseTopic}/thermostat/([^/]+)/target/set$`);
let match = msg.topic.match(regexThermostat);

// Se il topic non rispetta la struttura, ignoriamo il messaggio
if (!match || !match[1]) return null;

let room = match[1]; // Estrarrà "living", "bathroom", ecc.
let setpoint = parseFloat(msg.payload);

// Sicurezza: verifichiamo che il payload sia un numero valido
if (isNaN(setpoint)) {
    node.warn(`Setpoint non valido ricevuto per ${room}: ${msg.payload}`);
    return null;
}

let targetTopic = "";
let targetPayload = null;

switch(room) {
    case "living":
        // L'aria condizionata (Broadlink/IR) accetta solo gradi interi
        let gradiInteri = Math.round(setpoint);
        targetTopic = "zara/domotics/AC/command";
        targetPayload = gradiInteri.toString();
        break;

    case "bathroom":
        // Le valvole termostatiche Zigbee accettano i decimali (es. 21.5)
        targetTopic = "zigbee2mqtt/Termostato_Bagno/set";
        targetPayload = { current_heating_setpoint: setpoint };
        break;

    case "small_bathroom":
        targetTopic = "zigbee2mqtt/Termostato_Bagnetto/set";
        targetPayload = { current_heating_setpoint: setpoint };
        break;

    default:
        node.warn("Comando App per termostato non mappato: " + room);
        return null;
}

return {
    topic: targetTopic,
    payload: targetPayload
};

let inTopic = msg.topic;
let targetRoom = "";
let targetTemp = null;

if (inTopic === "casa/clima/stato_completo") {
    targetRoom = "living";
    targetTemp = msg.payload.stato_condizionatore.temperatura_impostata_c;
    if (targetTemp === 0) return null; 
}
else if (inTopic.includes("zigbee2mqtt/Termostato_Bagno")) {
    targetRoom = "bathroom";
    targetTemp = (typeof msg.payload === 'object') ? msg.payload.current_heating_setpoint : parseFloat(msg.payload);
}
else if (inTopic.includes("zigbee2mqtt/Termostato_Bagnetto")) {
    targetRoom = "small_bathroom";
    targetTemp = (typeof msg.payload === 'object') ? msg.payload.current_heating_setpoint : parseFloat(msg.payload);
}

if (targetRoom !== "" && targetTemp !== null && !isNaN(targetTemp)) {
    return {
        topic: `zara/android/domotica/thermostat/${targetRoom}/target/state`,
        payload: targetTemp
    };
}

return null;

// ============================================================================
// INBOUND ROUTER VMC
// Riceve comandi VMC dall'App e li formatta per l'hardware
// ============================================================================

let baseTopic = global.get("app_base_topic") || "zara/android/domotica";

// Usiamo una RegEx per estrarre la parola chiave (es. "speed") ignorando la lunghezza del prefisso
// Cerca il testo che si trova esattamente tra "/vmc/" e "/set"
let regexVmc = new RegExp(`^${baseTopic}/vmc/([^/]+)/set$`);
let match = msg.topic.match(regexVmc);

// Se il topic non corrisponde alla struttura attesa, scarta il messaggio
if (!match || !match[1]) return null;

let cmdType = match[1]; // Estrarrà "speed" in modo dinamico

if (cmdType === "speed") {
    let speed = parseInt(msg.payload);

    // Controllo di sicurezza: velocità da 1 a 4
    if (isNaN(speed) || speed < 1 || speed > 4) {
        node.warn("Comando VMC scartato. Valore non valido: " + msg.payload);
        return null;
    }

    // Output diretto verso il nodo MQTT hardware
    return {
        topic: "/esp8266/brink/fanspeed",
        payload: speed
    };
}

return null;

// Codice pulito per Outbound Router VMC
let inTopic = msg.topic;
let speed = null;

if (inTopic === "alexa/vmc") {
    speed = parseInt(msg.payload);
} else if (inTopic === "casa/clima/stato_completo") {
    if (msg.payload && msg.payload.stato_vmc) {
        speed = msg.payload.stato_vmc.velocita_attuale;
    }
}

if (speed !== null && !isNaN(speed)) {
    return {
        topic: "zara/android/domotica/vmc/speed/state",
        payload: speed.toString()
    };
}
return null;

// --- GATEWAY TELEMETRIE: AMBIENTI ---
let inTopic = msg.topic;
let rawPayload = msg.payload; // Non facciamo subito il parseFloat!

const APP_BASE = global.get("app_base_topic", "file") || "zara/android/domotica";

// Prepariamo un array che conterrà tutti i messaggi che vogliamo inviare all'App
let messaggiInUscita = [];

switch (inTopic) {
    // ==========================================
    // 1. SENSORI SEMPLICI (EmonCMS - Valore singolo)
    // ==========================================
    case "emon/emonth5/temperature_calibrated":
        if (!isNaN(parseFloat(rawPayload))) {
            messaggiInUscita.push({ topic: `${APP_BASE}/env/tempLiving`, payload: parseFloat(rawPayload).toString() });
        }
        break;

    case "emon/emonth5/humidity":
        if (!isNaN(parseFloat(rawPayload))) {
            messaggiInUscita.push({ topic: `${APP_BASE}/env/humLiving`, payload: parseFloat(rawPayload).toString() });
        }
        break;

    case "emon/cameraMatrimoniale/temperature":
        if (!isNaN(parseFloat(rawPayload))) {
            messaggiInUscita.push({ topic: `${APP_BASE}/env/tempBedroom`, payload: parseFloat(rawPayload).toString() });
        }
        break;

    case "emon/cameraMatrimoniale/humidity":
        if (!isNaN(parseFloat(rawPayload))) {
            messaggiInUscita.push({ topic: `${APP_BASE}/env/humBedroom`, payload: parseFloat(rawPayload).toString() });
        }
        break;

    // ==========================================
    // 2. SENSORI COMPLESSI (Zigbee2MQTT - JSON)
    // ==========================================
        // ==========================================
    case "zigbee2mqtt/Sonoff AirGuard TH camera matrimoniale":
        // I nodi MQTT di Node-RED con "auto-detect" convertono già il JSON in oggetto.
        // Verifichiamo che sia effettivamente un oggetto e non una stringa vuota.
        if (typeof rawPayload === 'object') {

            // Estraiamo la Temperatura
            if (rawPayload.temperature !== undefined) {
                messaggiInUscita.push({
                    topic: `${APP_BASE}/env/tempBedroom`,
                    payload: parseFloat(rawPayload.temperature).toString()
                });
            }

            // Estraiamo l'Umidità
            if (rawPayload.humidity !== undefined) {
                messaggiInUscita.push({
                    topic: `${APP_BASE}/env/humBedroom`,
                    payload: rawPayload.humidity.toString()
                });
            }
        }
        break;
    case "zigbee2mqtt/Sonoff AirGuard TH esterno cucina":
        // I nodi MQTT di Node-RED con "auto-detect" convertono già il JSON in oggetto.
        // Verifichiamo che sia effettivamente un oggetto e non una stringa vuota.
        if (typeof rawPayload === 'object') {

            // Estraiamo la Temperatura
            if (rawPayload.temperature !== undefined) {
                messaggiInUscita.push({
                    topic: `${APP_BASE}/env/tempOutdoor`,
                    payload: rawPayload.temperature.toString()
                });
            }

            // Estraiamo l'Umidità
            if (rawPayload.humidity !== undefined) {
                messaggiInUscita.push({
                    topic: `${APP_BASE}/env/humOutdoor`,
                    payload: rawPayload.humidity.toString()
                });
            }
        }
        break;

    default:
        return null; // Ignora altri topic non mappati
}

// Se non abbiamo preparato nessun messaggio (es. payload vuoti o errati), usciamo
if (messaggiInUscita.length === 0) {
    return null; 
}

// RESTITUZIONE MULTIPLA:
// L'array esterno [ ] rappresenta la "Porta di Uscita 1".
// La variabile messaggiInUscita è a sua volta un array [msgTemp, msgHum].
// Risultato finale: Node-RED "spara" i due messaggi in fila rapidissima verso l'App.
return [ messaggiInUscita ];

// ============================================================================
// INBOUND ROUTER SETTAGGI
// Riceve comandi globali e aggiorna memoria interna + interfaccia App
// ============================================================================

let baseTopic = global.get("app_base_topic", "file") || "zara/android/domotica";
let inTopic = msg.topic;
let rawPayload = msg.payload.toString().trim(); 

// Funzione di supporto per convertire stringhe in booleani reali
function parseBoolean(val) {
    if (val === "1" || val.toLowerCase() === "true") return true;
    if (val === "0" || val.toLowerCase() === "false") return false;
    return null;
}

let targetTopic = "";
let targetPayload = "";

switch (inTopic) {
    // 1. Abilitazione globale del sistema
    case `${baseTopic}/system/enabled/state`:
        let sysEnabled = parseBoolean(rawPayload);
        if (sysEnabled !== null) {
            targetTopic = "system";
            targetPayload = sysEnabled;
        }
        break;

    // 2. Modalità Vacanza (Antigelo)
    case `${baseTopic}/holiday/state`:
        let holidayMode = parseBoolean(rawPayload);
        if (holidayMode !== null) {
            targetTopic = "holiday";
            targetPayload = holidayMode;
        }
        break;

    // 3. Gestione AI Condizionatore
    case `${baseTopic}/ac_auto/state`:
        let acAuto = parseBoolean(rawPayload);
        if (acAuto !== null) {
            targetTopic = "ACAUTO"; // Nuovo topic interno per l'aggiornamento UI
            targetPayload = acAuto;
        }
        break;

    // 4. Luci notturne Eco
    case `${baseTopic}/eco_lights/state`:
        let ecoLights = parseBoolean(rawPayload);
        if (ecoLights !== null) {
            targetTopic = "luciECO";
            targetPayload = ecoLights;
        }
        break;

    // 5. Accensione automatica luci piscina
    case `${baseTopic}/pool_lights_auto/state`:
        let poolAuto = parseBoolean(rawPayload);
        if (poolAuto !== null) {
            targetTopic = "luciPiscinaAUTO";
            targetPayload = poolAuto;
        }
        break;

    // 6. Limite velocità VMC notturna
    case `${baseTopic}/vmc/maxNightSpeed/state`:
        let maxSpeed = parseInt(rawPayload);
        if (!isNaN(maxSpeed) && maxSpeed >= 1 && maxSpeed <= 4) {
            targetTopic = "vmc_night_limit";
            targetPayload = maxSpeed;
        } else {
            node.warn(`Valore VMC Notturna non valido: ${rawPayload}`);
        }
        break;

    default:
        return null;
}

// Invia il pacchetto allo Switch successivo per aggiornare lo stato (Retain) sull'App
if (targetTopic !== "") {
    return { topic: targetTopic, payload: targetPayload };
}

return null;

// ============================================================================
// APP MAIN ROUTER
// Riceve dal "Master Listener MQTT" e smista ai 4 Sub-Router (Outputs: 4)
// ============================================================================

let topic = msg.topic;
// Recupera il base topic dalla memoria globale (se non c'è, usa il default)
let baseTopic = global.get("app_base_topic") || "zara/android/domotica";

// Sicurezza: Ignora tutto ciò che non inizia con il nostro base topic
if (!topic.startsWith(baseTopic)) return null;

// Estraiamo il "path" utile rimuovendo la radice
// Es: "zara/android/domotica/light/sala/set" diventa "/light/sala/set"
let routingPath = topic.substring(baseTopic.length);

// Inizializziamo le 4 uscite come 'null' (nessun messaggio inviato di default)
let outLuci = null;         // Uscita 1
let outTermostati = null;   // Uscita 2
let outVmc = null;          // Uscita 3
let outSettaggi = null;     // Uscita 4

// Smistamento logico basato sull'inizio del percorso
if (routingPath.startsWith("/light/") || routingPath.startsWith("/scene/")) {
    outLuci = msg;
} 
else if (routingPath.startsWith("/thermostat/")) {
    outTermostati = msg;
} 
else if (routingPath.startsWith("/vmc/")) {
    // La VMC ha sia comandi diretti (/speed/set) che settaggi (/maxNightSpeed/set)
    if (routingPath.includes("/maxNightSpeed/set")) {
        outSettaggi = msg;
    } else {
        outVmc = msg;
    }
} 
else {
    // Tutti gli altri percorsi (system, holiday, eco_lights, ac_auto, ecc.)
    outSettaggi = msg;
}

// Ritorna esattamente 4 elementi per alimentare i 4 fili in uscita
return [outLuci, outTermostati, outVmc, outSettaggi];

// Nel Inbound Router Luci, invece di split('/') usa:
const APP_BASE = global.get("app_base_topic") || "zara/android/domotica";
// Questo estrae tutto ciò che c'è tra /light/ e /set
let match = msg.topic.match(new RegExp(APP_BASE + "\\/light\\/(.+?)\\/set"));
let device = match ? match[1] : null;

if (!device) return null; // Fallback se non è una luce

let cmd = msg.payload.toString().toUpperCase();
if (cmd === "TRUE" || cmd === "1") cmd = "ON";
if (cmd === "FALSE" || cmd === "0") cmd = "OFF";

let targetTopic = "";
let targetPayload = cmd;
let usaLinkInterno = false; // <-- Nuova variabile per il deviatoio

switch (device) {
    case "skimmerPiscina":
        targetPayload = cmd.toLowerCase(); // Trasforma ON in "on"
        usaLinkInterno = true;             // Attiva lo scambio verso l'uscita 2
        break;
    case "pompaPiscina":
        targetPayload = cmd.toLowerCase(); // Trasforma ON in "on"
        usaLinkInterno = true;             // Attiva lo scambio verso l'uscita 2
