const SampleTime = 500;

var setpoint = flow.get("setpoint") || 100;

if (msg.hasOwnProperty("setpoint")) {
    setpoint = msg.setpoint;
    node.status({ fill: "blue", shape: "dot", text: 'sp: ' + setpoint });
    flow.set("setpoint", setpoint);
}

// Negative for energy diverting
// -0.05 / -0.06 / -0.03
// -0.10 / -0.07 / -0.04
const kp = -0.10;
const ki = -0.08;
const kd = -0.04;
// const kp = -0.05;
// const ki = -0.06;
// const kd = -0.03;
const multiplier = 0.4;

// 0 / 1023
const outMin = -255;
const outMax = 255;

const pOnE = false; // Proportional on Error  else  Proportional on Measurement

const now = Date.now();
const lastTime = context.get('lastTime') || 0;
const timeChange = (now - lastTime);

const lastInput = context.get('lastInput') || msg.payload;
var outputSum = context.get("outputSum") || 0;

if (timeChange < SampleTime) return null;

/*Compute all the working error variables*/
var input = msg.payload,
    error = setpoint - input,
    dInput = (input - lastInput),
    output;

/*Compute integral*/
outputSum += (ki * error);

/*Compute proportional*/
if (pOnE) { output = kp * error; } /*Add Proportional on Error, if P_ON_E is specified*/
else { outputSum -= kp * dInput; output = 0; }  /*Add Proportional on Measurement, if P_ON_M is specified*/

if (outputSum > outMax) outputSum = outMax;
else if (outputSum < outMin) outputSum = outMin;

/*Compute derivative*/
output -= kd * dInput;

/*Merge*/
output += outputSum;

if (output > outMax) output = outMax;
else if (output < outMin) output = outMin;

output *= multiplier;
output = Math.round((output + Number.EPSILON) * 1000) / 1000;

/*Remember some variables for next time*/
context.set("lastInput", input);
context.set("lastTime", now);

const color = input < setpoint ? "red" : "green";
node.status({ fill: color, shape: "dot", text: 'sp: ' + setpoint + ', pid: ' + output });

return { topic: "pid", payload: output };

if (msg.payload.state == "on")
